.'=>'Les derniers numéros gagnants d’une loterie, avec la date du prochain tirage.','block keywordlottery'=>'loterie','block keywordlotto'=>'loto','block keywordresults'=>'résultats','block keywordwinning numbers'=>'numéros gagnants','block keywordpowerball'=>'powerball','block titleNext lottery draw'=>'Prochain tirage de loterie','block descriptionThe date of a lottery\'s next scheduled draw.'=>'La date du prochain tirage prévu d’une loterie.','block keywordnext draw'=>'prochain tirage','block keywordjackpot'=>'jackpot','block titleLottery results archive'=>'Archives des résultats de loterie','block descriptionA lottery\'s past draws, page by page. Needs a Lotalytics API key whose plan includes the archive.'=>'Les tirages passés d’une loterie, page par page. Nécessite une clé API Lotalytics dont l’offre inclut les archives.','block keywordarchive'=>'archives','block keywordhistory'=>'historique']];